import { expect, test as setup } from '@playwright/test';

const MAILPIT = `http://localhost:${process.env.MAILPIT_UI_PORT ?? '8025'}`;
export const STORAGE_STATE = 'test-results/.auth/user.json';

/**
 * Signs up a fresh user, completes email verification via the Mailpit API,
 * and persists the authenticated storage state for the main test project.
 * This IS the core signup→verify→session flow under test.
 */
setup('sign up and verify via Mailpit', async ({ page, request }) => {
  const email = `e2e-${Date.now()}@example.com`;

  // The wiped database makes this a FRESH instance: /signup forwards to
  // the first-run wizard (K1), which creates the admin auto-verified,
  // the organization, and the workspace in one shot — so every suite run
  // exercises the real first-install path.
  await page.goto('/signup');
  if (page.url().includes('/setup')) {
    await page.getByLabel('Your name').fill('E2E Operator');
    await page.getByLabel('Email').fill(email);
    await page.getByLabel('Password', { exact: true }).fill('correct-horse-battery');
    await page.getByLabel('Organization name').fill('E2E Org');
    // The suite owns its data — no sample workspace.
    await page.getByTestId('setup-seed').uncheck();
    await page.evaluate(() => localStorage.setItem('helio.tour.v1.done', '1'));
    await page.getByRole('button', { name: 'Create & enter Helio' }).click();
    await expect(page.getByRole('heading', { name: 'Overview' })).toBeVisible({
      timeout: 15_000,
    });
    await page.context().storageState({ path: STORAGE_STATE });
    return;
  }

  await page.getByLabel('Name').fill('E2E Operator');
  await page.getByLabel('Email').fill(email);
  await page.getByLabel('Password', { exact: true }).fill('correct-horse-battery');
  await page.getByRole('button', { name: 'Sign up' }).click();
  await expect(page.getByText('Check your email')).toBeVisible();

  // Fetch the verification link from Mailpit.
  let link: string | undefined;
  await expect
    .poll(
      async () => {
        const list = await request.get(`${MAILPIT}/api/v1/search?query=to:${email}`);
        const { messages } = (await list.json()) as { messages: Array<{ ID: string }> };
        if (!messages?.length) return false;
        const message = await request.get(`${MAILPIT}/api/v1/message/${messages[0]!.ID}`);
        const { Text } = (await message.json()) as { Text: string };
        link = Text.match(/https?:\/\/\S+verify-email\S+/)?.[0];
        return Boolean(link);
      },
      { timeout: 15_000 },
    )
    .toBe(true);

  // Visiting the link verifies the address and signs the user in; with no
  // organization yet, the dashboard redirects to onboarding.
  await page.goto(link!);
  await expect(page.getByText('Create your organization')).toBeVisible();
  await page.getByLabel('Organization name').fill('E2E Org');
  // Dismiss the product tour before the dashboard mounts so it never overlays
  // other specs; tour.spec re-enables it explicitly. Same origin as the app.
  await page.evaluate(() => localStorage.setItem('helio.tour.v1.done', '1'));
  await page.getByRole('button', { name: 'Create organization' }).click();
  await expect(page.getByRole('heading', { name: 'Overview' })).toBeVisible();

  await page.context().storageState({ path: STORAGE_STATE });
});

import RedisMock from 'ioredis-mock';
import { describe, expect, it, vi } from 'vitest';

import { createApp } from '../src/app';
import {
  applyEmailSuppression,
  postmarkSuppression,
  sesSuppression,
} from '../src/routes/email-webhook';
import type { GatewayDeps, RedisLike } from '../src/types';

const TOKEN = '[REDACTED]';

/** A Prisma stub: the resolver lookup plus contact/audit writes. */
function fakePrisma(contacts: Array<{ id: string; organizationId: string; workspaceId: string }>) {
  const updates: Array<{ where: unknown; data: Record<string, unknown> }> = [];
  const audits: Array<Record<string, unknown>> = [];
  const prisma: Record<string, unknown> = {
    // webhook_contacts_by_email runs as raw SQL (ADR-0017).
    $queryRaw: vi.fn().mockResolvedValue(contacts),
    contact: {
      update: vi.fn(async (args: (typeof updates)[number]) => {
        updates.push(args);
        return {};
      }),
    },
    auditLog: {
      create: vi.fn(async (args: { data: Record<string, unknown> }) => {
        audits.push(args.data);
        return {};
      }),
    },
  };
  // forTenant() extends the client; the stub hands back itself.
  prisma.$extends = () => prisma;
  return { prisma: prisma as never, updates, audits };
}

describe('postmarkSuppression', () => {
  it('suppresses a hard bounce', () => {
    expect(
      postmarkSuppression({ RecordType: 'Bounce', Type: 'HardBounce', Email: 'a@x.com' }),
    ).toEqual({ reason: 'BOUNCED', emails: ['a@x.com'], detail: 'HardBounce' });
  });

  it('suppresses a bad address and a spam complaint', () => {
    expect(
      postmarkSuppression({ RecordType: 'Bounce', Type: 'BadEmailAddress', Email: 'a@x.com' })
        ?.reason,
    ).toBe('BOUNCED');
    expect(postmarkSuppression({ RecordType: 'SpamComplaint', Email: 'a@x.com' })).toEqual({
      reason: 'COMPLAINED',
      emails: ['a@x.com'],
      detail: 'SpamComplaint',
    });
  });

  it('ignores transient bounces, other records, and missing addresses', () => {
    expect(
      postmarkSuppression({ RecordType: 'Bounce', Type: 'SoftBounce', Email: 'a@x.com' }),
    ).toBeNull();
    expect(
      postmarkSuppression({ RecordType: 'Bounce', Type: 'Transient', Email: 'a@x.com' }),
    ).toBeNull();
    expect(postmarkSuppression({ RecordType: 'Open', Email: 'a@x.com' })).toBeNull();
    expect(postmarkSuppression({ RecordType: 'Bounce', Type: 'HardBounce' })).toBeNull();
  });
});

describe('sesSuppression', () => {
  it('suppresses every recipient of a permanent bounce', () => {
    expect(
      sesSuppression({
        notificationType: 'Bounce',
        bounce: {
          bounceType: 'Permanent',
          bouncedRecipients: [{ emailAddress: 'a@x.com' }, { emailAddress: 'b@x.com' }],
        },
      }),
    ).toEqual({ reason: 'BOUNCED', emails: ['a@x.com', 'b@x.com'], detail: 'Permanent' });
  });

  it('ignores transient bounces and deliveries', () => {
    expect(
      sesSuppression({
        notificationType: 'Bounce',
        bounce: { bounceType: 'Transient', bouncedRecipients: [{ emailAddress: 'a@x.com' }] },
      }),
    ).toBeNull();
    expect(sesSuppression({ notificationType: 'Delivery' })).toBeNull();
  });

  it('suppresses complaints with the feedback type as detail', () => {
    expect(
      sesSuppression({
        notificationType: 'Complaint',
        complaint: {
          complainedRecipients: [{ emailAddress: 'a@x.com' }],
          complaintFeedbackType: 'abuse',
        },
      }),
    ).toEqual({ reason: 'COMPLAINED', emails: ['a@x.com'], detail: 'abuse' });
  });
});

describe('applyEmailSuppression', () => {
  it('flips every matched contact and audit-logs each, per tenant', async () => {
    const { prisma, updates, audits } = fakePrisma([
      { id: 'c1', organizationId: 'org_1', workspaceId: 'ws_1' },
      { id: 'c2', organizationId: 'org_2', workspaceId: 'ws_2' },
    ]);
    const result = await applyEmailSuppression(
      prisma,
      { reason: 'BOUNCED', emails: ['Bad@X.com'], detail: 'HardBounce' },
      'postmark',
    );
    expect(result.suppressed).toBe(2);
    expect(updates.map((u) => u.data.status)).toEqual(['BOUNCED', 'BOUNCED']);
    expect(audits[0]).toMatchObject({
      action: 'contact.bounced',
      organizationId: 'org_1',
      workspaceId: 'ws_1',
      metadata: { via: 'email_webhook', provider: 'postmark', detail: 'HardBounce' },
    });
    expect(audits[1]).toMatchObject({ organizationId: 'org_2' });
  });

  it('records complaints under their own audit action', async () => {
    const { prisma, audits } = fakePrisma([
      { id: 'c1', organizationId: 'org_1', workspaceId: 'ws_1' },
    ]);
    await applyEmailSuppression(
      prisma,
      { reason: 'COMPLAINED', emails: ['a@x.com'], detail: 'abuse' },
      'ses',
    );
    expect(audits[0]!.action).toBe('contact.complained');
  });
});

describe('POST /webhooks/email/:provider', () => {
  function makeApp(
    contacts: Array<{ id: string; organizationId: string; workspaceId: string }> = [],
    emailWebhook?: GatewayDeps['emailWebhook'],
  ) {
    const fakes = fakePrisma(contacts);
    const app = createApp({
      prisma: fakes.prisma,
      redis: new RedisMock() as unknown as RedisLike,
      rateLimit: { max: 1000, windowSeconds: 3600 },
      emailWebhook,
    });
    return { app, ...fakes };
  }

  const config = (fetcher = vi.fn().mockResolvedValue(undefined)) => ({
    token: TOKEN,
    fetch: fetcher,
  });

  it('404s when not configured', async () => {
    const { app } = makeApp();
    const response = await app.request('/webhooks/email/postmark?token=x', {
      method: 'POST',
      body: '{}',
    });
    expect(response.status).toBe(404);
  });

  it('401s on a wrong token and 404s on an unknown provider', async () => {
    const { app } = makeApp([], config());
    const bad = await app.request('/webhooks/email/postmark?token=wrong', {
      method: 'POST',
      body: '{}',
    });
    expect(bad.status).toBe(401);
    const unknown = await app.request(`/webhooks/email/sendgrid?token=${TOKEN}`, {
      method: 'POST',
      body: '{}',
    });
    expect(unknown.status).toBe(404);
  });

  it('suppresses on a Postmark hard bounce', async () => {
    const { app, updates } = makeApp(
      [{ id: 'c1', organizationId: 'org_1', workspaceId: 'ws_1' }],
      config(),
    );
    const response = await app.request(`/webhooks/email/postmark?token=${TOKEN}`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ RecordType: 'Bounce', Type: 'HardBounce', Email: 'a@x.com' }),
    });
    expect(response.status).toBe(200);
    expect(await response.json()).toEqual({ received: true, suppressed: 1 });
    expect(updates).toHaveLength(1);
  });

  it('acknowledges but does not suppress a soft bounce', async () => {
    const { app, updates } = makeApp(
      [{ id: 'c1', organizationId: 'org_1', workspaceId: 'ws_1' }],
      config(),
    );
    const response = await app.request(`/webhooks/email/postmark?token=${TOKEN}`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ RecordType: 'Bounce', Type: 'SoftBounce', Email: 'a@x.com' }),
    });
    expect(await response.json()).toEqual({ received: true, suppressed: 0 });
    expect(updates).toHaveLength(0);
  });

  it('confirms an SNS subscription only on a real AWS https URL', async () => {
    const fetcher = vi.fn().mockResolvedValue(undefined);
    const { app } = makeApp([], config(fetcher));
    const ok = await app.request(`/webhooks/email/ses?token=${TOKEN}`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        Type: 'SubscriptionConfirmation',
        SubscribeURL: 'https://sns.eu-west-1.amazonaws.com/?Action=ConfirmSubscription&Token=t',
      }),
    });
    expect(ok.status).toBe(200);
    expect(fetcher).toHaveBeenCalledTimes(1);

    // A forged envelope pointing anywhere else is refused — no SSRF.
    const evil = await app.request(`/webhooks/email/ses?token=${TOKEN}`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        Type: 'SubscriptionConfirmation',
        SubscribeURL: 'https://attacker.example.com/steal',
      }),
    });
    expect(evil.status).toBe(400);
    expect(fetcher).toHaveBeenCalledTimes(1);
  });

  it('unwraps a stringified SNS Message and suppresses its recipients', async () => {
    const { app, updates } = makeApp(
      [{ id: 'c1', organizationId: 'org_1', workspaceId: 'ws_1' }],
      config(),
    );
    const response = await app.request(`/webhooks/email/ses?token=${TOKEN}`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        Type: 'Notification',
        Message: JSON.stringify({
          notificationType: 'Complaint',
          complaint: { complainedRecipients: [{ emailAddress: 'a@x.com' }] },
        }),
      }),
    });
    expect(await response.json()).toEqual({ received: true, suppressed: 1 });
    expect(updates[0]!.data.status).toBe('COMPLAINED');
  });
});

import { Hono } from 'hono';
import { describe, expect, it } from 'vitest';

import { rateLimit } from '../src/middleware/rate-limit';
import type { RedisLike } from '../src/types';

function appWith(redis: RedisLike) {
  const app = new Hono();
  app.use('*', rateLimit(redis, { max: 2, windowSeconds: 60 }));
  app.get('/', (c) => c.text('ok'));
  return app;
}

function countingRedis(): RedisLike {
  const store = new Map<string, number>();
  return {
    incr: async (key: string) => {
      const next = (store.get(key) ?? 0) + 1;
      store.set(key, next);
      return next;
    },
    expire: async () => 1,
    ttl: async () => 60,
    get: async () => null,
    set: async () => 'OK',
    ping: async () => 'PONG',
  } as unknown as RedisLike;
}

function brokenRedis(): RedisLike {
  const down = async () => {
    throw new Error('ECONNREFUSED');
  };
  return {
    incr: down,
    expire: down,
    ttl: down,
    get: down,
    set: down,
    ping: down,
  } as unknown as RedisLike;
}

const auth = (key: string) => ({ headers: { authorization: key } });

describe('rate-limit middleware', () => {
  it('allows up to the limit, then 429s with Retry-After', async () => {
    const app = appWith(countingRedis());
    expect((await app.request('/', auth('k1'))).status).toBe(200);
    expect((await app.request('/', auth('k1'))).status).toBe(200);
    const limited = await app.request('/', auth('k1'));
    expect(limited.status).toBe(429);
    expect(limited.headers.get('retry-after')).toBeTruthy();
    expect(limited.headers.get('ratelimit-limit')).toBe('2');
  });

  it('tracks budgets per credential', async () => {
    const app = appWith(countingRedis());
    await app.request('/', auth('a'));
    await app.request('/', auth('a'));
    expect((await app.request('/', auth('a'))).status).toBe(429);
    // A different credential still has its full budget.
    expect((await app.request('/', auth('b'))).status).toBe(200);
  });

  it('degrades to an in-memory limit when Redis is down (no 500)', async () => {
    const app = appWith(brokenRedis());
    expect((await app.request('/', auth('k2'))).status).toBe(200);
    expect((await app.request('/', auth('k2'))).status).toBe(200);
    // The fallback still enforces the window — a Redis outage must not 500
    // every request, nor lift the limit entirely.
    expect((await app.request('/', auth('k2'))).status).toBe(429);
  });
});

import { Hono } from 'hono';
import { describe, expect, it } from 'vitest';

import { idempotency } from '../src/middleware/idempotency';
import type { GatewayEnv, RedisLike } from '../src/types';

/** A tiny in-memory Redis with the get/set/EX shape the middleware uses. */
function memRedis(): RedisLike {
  const store = new Map<string, string>();
  return {
    get: async (key: string) => store.get(key) ?? null,
    set: async (key: string, value: string) => {
      store.set(key, value);
      return 'OK';
    },
    incr: async () => 1,
    expire: async () => 1,
    ttl: async () => 60,
    ping: async () => 'PONG',
  } as unknown as RedisLike;
}

// Stand in for apiKeyAuth: set the org from a header so each request can act as
// a different tenant, exactly as the real middleware order does.
function appFor(redis: RedisLike) {
  const app = new Hono<GatewayEnv>();
  app.use('*', async (c, next) => {
    c.set('organizationId', c.req.header('x-org') ?? 'none');
    await next();
  });
  app.use('*', idempotency(redis));
  let counter = 0;
  app.post('/v1/contacts', (c) => c.json({ org: c.get('organizationId'), n: ++counter }));
  return app;
}

describe('idempotency middleware', () => {
  it('replays the stored response for the same org + key', async () => {
    const app = appFor(memRedis());
    const headers = { 'idempotency-key': 'k1', 'x-org': 'orgA' };
    const first = await app.request('/v1/contacts', { method: 'POST', headers });
    const second = await app.request('/v1/contacts', { method: 'POST', headers });
    expect(await second.json()).toEqual(await first.json());
    expect(second.headers.get('Idempotency-Replayed')).toBe('true');
  });

  it('never leaks one tenant response to another sharing the same key', async () => {
    const app = appFor(memRedis());
    const a = await app.request('/v1/contacts', {
      method: 'POST',
      headers: { 'idempotency-key': 'order-123', 'x-org': 'orgA' },
    });
    const b = await app.request('/v1/contacts', {
      method: 'POST',
      headers: { 'idempotency-key': 'order-123', 'x-org': 'orgB' },
    });
    expect(((await a.json()) as { org: string }).org).toBe('orgA');
    // Org B must run its own handler, not receive org A's cached body.
    expect(((await b.json()) as { org: string }).org).toBe('orgB');
    expect(b.headers.get('Idempotency-Replayed')).toBeNull();
  });
});

import { redirect } from 'next/navigation';

import { authDb } from '@/lib/auth';

import { SetupWizard } from './setup-wizard';

// Instance state (is anyone registered yet?) must be read per request —
// this page cannot be prerendered at build time, where no database exists.
export const dynamic = 'force-dynamic';

/** First-run only: the moment a user exists, this page is gone. */
export default async function SetupPage() {
  const users = await authDb.user.count();
  if (users > 0) redirect('/login');
  return <SetupWizard />;
}

'use client';

import { Button } from '@helio/ui/components/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@helio/ui/components/card';
import { Input } from '@helio/ui/components/input';
import { Label } from '@helio/ui/components/label';
import { PasswordInput } from '@helio/ui/components/password-input';
import { useMutation } from '@tanstack/react-query';
import { Sun } from 'lucide-react';
import { useRouter } from 'next/navigation';
import { useTranslations } from 'next-intl';
import { useState } from 'react';
import { toast } from 'sonner';

import { passwordScore, PasswordStrength } from '@/components/password-strength';
import { authClient } from '@/lib/auth-client';
import { useTRPC } from '@/trpc/client';

/**
 * First-run setup (K1): one screen creates the admin (auto-verified — no
 * mail loop exists yet), the organization, and the first workspace, then
 * signs straight in. Email/AI/branding/demo-data all live in Settings,
 * where the dashboard's onboarding checklist points next — the wizard
 * stays short on purpose: a non-technical operator should be inside the
 * product in under a minute.
 */
export function SetupWizard() {
  const t = useTranslations('setup');
  const trpc = useTRPC();
  const router = useRouter();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [organizationName, setOrganizationName] = useState('');
  const [seedDemo, setSeedDemo] = useState(true);
  const [working, setWorking] = useState(false);
  const bootstrap = useMutation(trpc.setup.bootstrap.mutationOptions());

  async function onSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setWorking(true);
    try {
      await bootstrap.mutateAsync({ name, email, password, organizationName, seedDemo });
      const signIn = await authClient.signIn.email({ email, password });
      if (signIn.error) throw new Error(signIn.error.message ?? t('signInFailed'));
      router.push('/');
      router.refresh();
    } catch (error) {
      toast.error(error instanceof Error ? error.message : t('genericError'));
      setWorking(false);
    }
  }

  return (
    <div className="grid min-h-svh place-items-center p-4">
      <Card className="w-full max-w-md" data-testid="setup-wizard">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-xl">
            <Sun className="text-primary size-5" aria-hidden /> {t('title')}
          </CardTitle>
          <CardDescription>{t('subtitle')}</CardDescription>
        </CardHeader>
        <CardContent>
          <form className="grid gap-4" onSubmit={onSubmit}>
            <div className="grid gap-1.5">
              <Label htmlFor="setup-name">{t('name')}</Label>
              <Input
                id="setup-name"
                required
                maxLength={120}
                value={name}
                onChange={(event) => setName(event.target.value)}
              />
            </div>
            <div className="grid gap-1.5">
              <Label htmlFor="setup-email">{t('email')}</Label>
              <Input
                id="setup-email"
                type="email"
                required
                value={email}
                onChange={(event) => setEmail(event.target.value)}
              />
              <p className="text-muted-foreground text-xs">{t('emailHint')}</p>
            </div>
            <div className="grid gap-1.5">
              <Label htmlFor="setup-password">{t('password')}</Label>
              <PasswordInput
                id="setup-password"
                required
                minLength={10}
                value={password}
                onChange={(event) => setPassword(event.target.value)}
              />
              <PasswordStrength password={password} />
              <p className="text-muted-foreground text-xs">{t('passwordHint')}</p>
            </div>
            <div className="grid gap-1.5">
              <Label htmlFor="setup-org">{t('organization')}</Label>
              <Input
                id="setup-org"
                required
                maxLength={120}
                value={organizationName}
                onChange={(event) => setOrganizationName(event.target.value)}
              />
            </div>
            <label className="flex items-center gap-2 text-sm">
              <input
                type="checkbox"
                className="accent-primary size-4"
                checked={seedDemo}
                onChange={() => setSeedDemo((current) => !current)}
                data-testid="setup-seed"
              />
              {t('seedDemo')}
            </label>
            <Button type="submit" disabled={working || passwordScore(password) < 2}>
              {working ? t('working') : t('start')}
            </Button>
            <p className="text-muted-foreground text-xs">{t('afterNote')}</p>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

