import { describe, expect, it } from 'vitest';

/**
 * Guards the self-host compose that ships in the install bundle. ClickHouse
 * does a slow first-boot init (create user + database) before its HTTP port
 * binds; on a cold disk that outran the healthcheck and `compose up --wait`
 * declared the whole install failed. These invariants keep the fix in place.
 */
const selfhost = readFileSync(
  new URL('../../../infra/compose/docker-compose.selfhost.yml', import.meta.url),
  'utf8',
);

/** The body of one top-level (two-space-indented) service block. */
function serviceBlock(compose: string, name: string): string {
  const lines = compose.split('\n');
  const start = lines.indexOf(`  ${name}:`);
  if (start === -1) throw new Error(`service "${name}" not found in compose`);
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i += 1) {
    if (/^ {2}\S/.test(lines[i] ?? '')) {
      end = i;
      break;
    }
  }
  return lines.slice(start, end).join('\n');
}

describe('self-host compose: ClickHouse startup resilience', () => {
  const clickhouse = serviceBlock(selfhost, 'clickhouse');

  it('has a healthcheck', () => {
    expect(clickhouse).toMatch(/healthcheck:/);
  });

  it('grants a start_period so first-boot init does not trip `up --wait`', () => {
    expect(clickhouse).toMatch(/start_period:\s*\d+s/);
  });

  it('raises the file-descriptor limit to the ClickHouse-recommended value', () => {
    expect(clickhouse).toMatch(/nofile:\s*262144/);
  });
});

describe('self-host compose: in-app update sidecar', () => {
  const updater = serviceBlock(selfhost, 'updater');

  it('runs behind its own optional `update` profile', () => {
    expect(updater).toMatch(/profiles:\s*\['update'\]/);
  });

  it('is the ONLY container that mounts the Docker socket', () => {
    // One mount line per service that binds the socket — only the updater may.
    const mounts = selfhost.match(/-\s*\/var\/run\/docker\.sock:/g) ?? [];
    expect(mounts).toHaveLength(1);
    expect(updater).toContain('/var/run/docker.sock:/var/run/docker.sock');
  });

  it('requires the shared update secret', () => {
    expect(updater).toMatch(/HELIO_UPDATE_SECRET:[REDACTED];
  });

  it('pins the updater image to the release version placeholder', () => {
    // The release retags this byte-identically when only other code changed;
    // the placeholder keeps the sidecar on the same version as the stack.
    expect(updater).toMatch(/image:\s*ghcr\.io\/achref-soua\/helio-updater:__HELIO_VERSION__/);
  });

  it('shares the update-state volume with the web app', () => {
    expect(selfhost).toMatch(/^ {2}update-state:\s*$/m);
    expect(serviceBlock(selfhost, 'web')).toContain('update-state:/var/lib/helio/update-state');
    expect(updater).toContain('update-state:/state');
  });

  it('keeps the dashboard update toggle off by default in the stack', () => {
    expect(serviceBlock(selfhost, 'web')).toMatch(
      /HELIO_INAPP_UPDATE:\s*\$\{HELIO_INAPP_UPDATE:-false\}/,
    );
  });
});

# @helio/sdk-js

Helio's JS/TS SDK. Two zero-dependency clients:

- **`@helio/sdk-js`** — the browser tracking client (`track` / `identify` /
  `page`), below.
- **`@helio/sdk-js/rest`** — a typed client for the public REST API (manage
  contacts, lists, and workspaces server-side), [further down](#rest-api-client).

## Browser tracking

Zero dependencies, ~2 kB of logic: queue, batch, and deliver events to a
Helio ingestion endpoint, with `sendBeacon` flushing when the page goes away.

## Usage

```ts
import { HelioClient } from '@helio/sdk-js';

const helio = new HelioClient({
  writeKey: 'wk_…', // Workspace write key (Settings → Sources)
  host: 'https://ingest.your-helio.example',
});

helio.page('Pricing');
helio.track('Signed Up', { plan: 'pro' });
helio.identify('user-42', { email: 'ada@example.com' });
helio.reset(); // on logout
await helio.flush(); // usually unnecessary — batching handles it
```

## Behavior

- **Identity** — a per-browser `anonymousId` persists in localStorage
  (memory fallback when unavailable); `identify()` pins a `userId` that
  rides every later event until `reset()`.
- **Batching** — events flush at `flushAt` (default 20) or after
  `flushIntervalMs` (default 5 s), whichever comes first.
- **Page exit** — `pagehide`/`visibilitychange: hidden` flush via
  `navigator.sendBeacon` (the write key travels in the body, which the
  ingestion endpoint accepts precisely for this).
- **Failures** — 5xx and network errors requeue (capped at
  `maxQueueSize`, default 1000, oldest dropped); 4xx are permanent and
  the batch is discarded rather than retried forever.
- **SSR-safe** — every browser API is feature-checked; importing on the
  server is harmless.

## REST API client

A typed wrapper over the public gateway. The types are generated from the
gateway's OpenAPI document (`pnpm --filter @helio/sdk-js generate`, kept in
sync by a test), so the client always matches the live contract. Runs
anywhere `fetch` exists; the API key grants full org access, so use it
**server-side only**.

```ts
import { HelioApiClient, HelioApiError } from '@helio/sdk-js/rest';

const helio = new HelioApiClient({
  apiKey: [REDACTED], // hk_<org>.<secret> from Settings → API keys
  baseUrl: 'https://api.your-helio.example',
});

const contact = await helio.contacts.create(
  { workspaceId: 'ws_…', email: 'jane@example.com', firstName: 'Jane' },
  { idempotencyKey: crypto.randomUUID() },
);

const list = await helio.lists.create({ workspaceId: 'ws_…', name: 'VIPs' });
await helio.lists.addMembers(list.id, [contact.id]);

// Cursor pagination.
let cursor: string | null = null;
do {
  const page = await helio.contacts.list({ workspaceId: 'ws_…', cursor: cursor ?? undefined });
  for (const c of page.data) console.log(c.email);
  cursor = page.nextCursor;
} while (cursor);

try {
  await helio.contacts.get('contact_missing');
} catch (error) {
  if (error instanceof HelioApiError) console.error(error.status, error.type, error.detail);
}
```

Resources: `workspaces` (list/create), `contacts` (list/create/get/update/delete),
`lists` (list/create/get/delete/addMembers/removeMember). Every non-2xx
response throws a `HelioApiError` carrying the RFC 9457 problem document.

import { existsSync } from 'node:fs';
import path from 'node:path';
import { loadEnvFile } from 'node:process';

import { Client } from 'pg';

/**
 * Deterministic E2E: every suite starts from an empty LOCAL development
 * database and an empty mailbox. Truncates all tables (migrations table
 * excluded) over DATABASE_ADMIN_URL — owner-consented, dev-only wipe;
 * point this at nothing you care about.
 */
export default async function globalSetup() {
  const rootEnv = path.resolve(import.meta.dirname, '../../../.env');
  if (existsSync(rootEnv)) loadEnvFile(rootEnv);

  const connectionString = process.env.DATABASE_ADMIN_URL;
  if (!connectionString) throw new Error('DATABASE_ADMIN_URL must be set for e2e');
  if (!/localhost|127\.0\.0\.1|postgres:/.test(connectionString)) {
    throw new Error('Refusing to wipe a non-local database in e2e global setup');
  }

  const client = new Client({ connectionString });
  await client.connect();
  try {
    const { rows } = await client.query<{ tablename: string }>(
      `SELECT tablename FROM pg_tables
       WHERE schemaname = 'public' AND tablename <> '_prisma_migrations'`,
    );
    if (rows.length > 0) {
      const tables = rows.map((row) => `"${row.tablename}"`).join(', ');
      await client.query(`TRUNCATE ${tables} RESTART IDENTITY CASCADE`);
    }
  } finally {
    await client.end();
  }

  // Resolved here, not at module load — MAILPIT_UI_PORT comes from the
  // root .env read above, so an import-time constant would miss it.
  const mailpit = `http://localhost:${process.env.MAILPIT_UI_PORT ?? '8025'}`;
  await fetch(`${mailpit}/api/v1/messages`, { method: 'DELETE' });
}

